from pathlib import Path
import base64,json,subprocess
root=Path(__file__).resolve().parents[1];cases={}
for actor,label in [('rafi','רפי'),('shaul','שאול')]:
    for mode in ['manual','classic','hybrid']:
        tag='full-'+actor+'-'+mode;run=json.loads((root/'evidence/m476'/f'{tag}.json').read_text());clip=root/'evidence/m476'/f'{tag}.webm'
        probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration:stream=codec_name,width,height','-of','json',str(clip)]))
        assert run['pass'] and probe['streams'][0]['codec_name']=='vp8'
        cases[tag]={'label':label+' · '+mode.title(),'src':'data:video/webm;base64,'+base64.b64encode(clip.read_bytes()).decode(),'duration':float(probe['format']['duration']),'milestones':[{'name':m['name'],'t':round(m['t'],2),'x':round(m['x'],1),'gear':','.join(m['gear'])} for m in run['marks']]}
css='body{margin:24px;background:#071d22;color:#e2eee7;font:16px system-ui}main{max-width:1280px;margin:auto}p{line-height:1.6;color:#bdd3c9}nav{display:flex;flex-wrap:wrap;gap:8px}button{background:#163c3b;color:#e7f6ed;border:1px solid #77b49a;border-radius:8px;padding:12px;cursor:pointer}button[aria-pressed=true]{background:#b6dfc6;color:#082522}video{width:100%;max-height:74vh;background:black;margin:16px 0}table{width:100%;border-collapse:collapse}td,th{text-align:right;padding:8px;border-bottom:1px solid #375951}.status{color:#d9bf7a}'
page='''<!doctype html><html lang="he" dir="rtl"><meta charset="utf-8"><title>Rafael Brothers M4.7.6 — Full Runs</title><style>'''+css+'''</style><main><h1>האחים רפאל — M4.7.6</h1><p>שש ריצות אוטומטיות רציפות מה־Spawn המקורי עד שער היציאה. קלט מקלדת אמיתי, מצלמה רגילה, ללא Teleport, שינוי מהירויות או הפעלת טריגרים מלאכותית. כל סרטון כולל את התצוגה המקורית ואת בחירת מצב הסרט; אין חיבור של מקטעים נפרדים.</p><nav id="cases"></nav><h2 id="title"></h2><p id="status" class="status"></p><video id="movie" controls playsinline preload="metadata"></video><p>הששיות הושלמו ב־Chromium Canvas. WebGL עבר בדיקת פתיחה וכלים, אך שתי ריצות מלאות בו נעצרו לפני השלמת הבור הראשון: NOT PROVEN. נוחות חזותית, הנאה ואישור אנושי עדיין ממתינים לבדיקה שלך; Safari לא נבדק.</p><h2>נקודות ההתקדמות בריצה</h2><p>הזמנים בטבלה הם שעון המשחק, לא זמן הנגן. הסרטונים שומרים את משך הלכידה המקורי.</p><table><thead><tr><th>נקודה</th><th>שניות במשחק</th><th>X</th><th>כלים</th></tr></thead><tbody id="timeline"></tbody></table><p>הפטיש נאסף כבר בחפיפה באזור ההתחלה; הסרט נאסף בהמשך והמקדחה נמצאת מתחת למדף. ההכוונה עודכנה, בלי להזיז אותם או לשנות מכניקות. בדיקות מוות/התאוששות ומתגים הן ראיות נפרדות ומפורטות בדוח QA.</p></main><script>const CASES='''+json.dumps(cases,ensure_ascii=False)+''';const movie=document.getElementById('movie'),nav=document.getElementById('cases');function select(key){movie.pause();movie.src=CASES[key].src;movie.dataset.case=key;document.getElementById('title').textContent=CASES[key].label;document.getElementById('status').textContent='PASS · ריצה רציפה · '+CASES[key].duration.toFixed(2)+' שניות וידאו · ללא מוות';for(const b of nav.children)b.setAttribute('aria-pressed',String(b.dataset.case===key));const body=document.getElementById('timeline');body.replaceChildren();for(const m of CASES[key].milestones){const tr=document.createElement('tr');for(const v of [m.name,m.t,m.x,m.gear]){const td=document.createElement('td');td.textContent=v;tr.append(td);}body.append(tr);}}for(const [key,c] of Object.entries(CASES)){const b=document.createElement('button');b.textContent=c.label;b.dataset.case=key;b.onclick=()=>select(key);nav.append(b);}select(Object.keys(CASES)[0]);</script></html>'''
(root/'M476_GAMEPLAY_GALLERY.html').write_text(page)
(root/'evidence/m476/video-integrity.json').write_text(json.dumps({'checks':[{'name':k+' native VP8 metadata integrity','passed':True,'duration':c['duration']} for k,c in cases.items()]},indent=2)+'\n');print('6 complete native videos embedded')
